function schedule() {
const grids = [...embedRoot.querySelectorAll(".sgrid")];
if (!grids.length) return;
const wide = window.matchMedia("(min-width: 1100px)");
const mins = (t) => {
const [h, m] = t.split(":").map(Number);
return h * 60 + m;
};
const label = (m) => {
const h = Math.floor(m / 60);
return (h % 12 || 12) + ":" + String(m % 60).padStart(2, "0") +
(h < 12 || h >= 24 ? "AM" : "PM");
};
for (const g of grids) {
const cols = g.dataset.cols.split("|").map((s) => s.trim());
const from = mins(g.dataset.from);
const to = mins(g.dataset.to);
g.style.setProperty("--cols", cols.length);
const row = (m) => 4 + (m - from) / 15;
for (const li of g.querySelectorAll("li[data-from]")) {
const s = row(mins(li.dataset.from));
let e = row(mins(li.dataset.to));
if (e <= s) e = s + 2;
li.style.setProperty("--s", s);
li.style.setProperty("--e", e);
const c = cols.indexOf(li.dataset.at);
li.style.setProperty("--c", c < 0 ? 0 : c + 1);
}
const deco = (cls) => {
const li = document.createElement("li");
li.className = cls;
li.setAttribute("aria-hidden", "true");
g.appendChild(li);
return li;
};
g.style.setProperty("--rowend", row(to) + 1);
deco("timecol");
deco("colhead loc").textContent = "Locations";
const CHEV =
'<span class="chev">' +
'<svg class="c1" viewBox="0 0 162.708 227"><use href="#m-chev-1"/></svg>' +
'<svg class="c2" viewBox="0 0 162.708 227"><use href="#m-chev-1"/></svg>' +
"</span>";
cols.forEach((name, i) => {
const li = deco("colhead");
li.style.setProperty("--c", i + 1);
li.innerHTML = CHEV;
li.append(name);
});
cols.forEach((_, i) => {
deco("vrule").style.setProperty("--c", i + 1);
});
deco("vrule last").style.setProperty("--c", cols.length);
for (let m = from; m <= to; m += 60) {
const lab = deco("hour");
lab.style.setProperty("--s", row(m));
const t = document.createElement("time");
t.textContent = label(m);
lab.appendChild(t);
deco("hrule").style.setProperty("--s", row(m));
if (m + 30 <= to) {
deco("hhalf").style.setProperty("--s", row(m + 30));
}
}
}
const trackCount = Math.max(
...grids.map((g) => g.dataset.cols.split("|").length),
);
grids.forEach((g) => g.style.setProperty("--tracks", trackCount));
const STEP = 8;
const demand = (li) => {
const c = getComputedStyle(li);
const quarters =
+li.style.getPropertyValue("--e") - +li.style.getPropertyValue("--s");
if (!(quarters > 0)) return 0;
const kids = [...li.children];
const h =
parseFloat(c.paddingTop) +
parseFloat(c.paddingBottom) +
parseFloat(c.marginTop) +
parseFloat(c.marginBottom) +
(parseFloat(c.rowGap) || 0) * (kids.length - 1) +
kids.reduce((a, k) => a + k.getBoundingClientRect().height, 0);
return h / quarters;
};
const sizeRows = () => {
for (const g of grids) {
if (!g.classList.contains("is-grid")) continue;
const events = [...g.querySelectorAll("li[data-from]")];
let need = 0;
for (const li of events) need = Math.max(need, demand(li));
let row = Math.max(40, Math.ceil(need / STEP) * STEP);
g.style.setProperty("--q", row + "px");
for (let pass = 0; pass < 2; pass++) {
const short = events.some(
(li) => demand(li) > row + 0.5,
);
if (!short) break;
row += STEP;
g.style.setProperty("--q", row + "px");
}
}
};
const measure = () => {
for (const g of grids) {
const date = g.closest(".sday")?.querySelector(".sdate");
if (date) g.style.setProperty("--dateh", date.offsetHeight + "px");
}
sizeRows();
};
const apply = () => {
grids.forEach((g) => g.classList.toggle("is-grid", wide.matches));
measure();
};
apply();
wide.addEventListener("change", apply);
addEventListener("resize", measure);
if (document.fonts && document.fonts.ready) {
document.fonts.ready.then(measure);
}
}
schedule();
